using OcctSharp.ExchangeRoots;
using OcctSharp.MeshBoundaryDiagnostics;
using OcctSharp.MeshingWorkspaces;
using OcctSharp.PolyWorkspaces;
using OcctSharp.DocumentProjections;
using OcctSharp.DocumentAssociations;
using OcctSharp.SelectionWorkspaces;
using OcctSharp.Values;
namespace OcctSharp.Tests.Shared;
internal static class BatchBEMeshWorkflow {
 internal static void Require(bool value,string message){if(!value)throw new InvalidOperationException("BE: "+message);}
 internal static void Run(){string root=Path.Combine(Path.GetTempPath(),"OcctSharp.BE."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string step=Path.Combine(root,"source.step");using var box=ShapeFactory.CreateBox(4,3,2);ShapeExchange.WriteStep(box,step);using var read=ExchangeRootWorkspace.Open(step);using var selected=read.Transfer([read.Snapshot().Roots.Single().Id]);using var source=selected.GetShape(0);selected.Dispose();read.Dispose();using var meshing=ControlledMeshing.Run(source,new(Deflection:.05));Require(meshing.IsDone&&meshing.HasCompleteTriangulation,"controlled meshing");using var meshed=meshing.CopyShape();var mesh=MeshTopology.SnapshotExisting(meshed).Mesh;using var poly=PolyDataWorkspaces.FromMesh(mesh);using var triangulation=poly.CopyTriangulation();using var inputSnapshot=PolyDataWorkspaces.Copy(triangulation);var exactMesh=inputSnapshot.Mesh;Require(exactMesh.Positions.SequenceEqual(mesh.Positions)&&exactMesh.Triangles.Select(x=>(x.A,x.B,x.C)).SequenceEqual(mesh.Triangles.Select(x=>(x.A,x.B,x.C))),"native input ordinal mapping");using var quality=MeshBoundaryComputations.Analyze(triangulation);var data=quality.Diagnostic;Require(data.Triangles.Count==mesh.Triangles.Count&&data.NodeCount==mesh.Positions.Count&&data.DegenerateTriangles==0&&data.Edges.Count>0&&data.NativeFreeNodeIndices is not null,"exact copied quality/adjacency");var face=MeshBoundaryComputations.FaceBoundary(meshed,0);Require(face.Edges.Count==4&&face.Edges.All(x=>x.Range2d is not null&&x.Range3d is not null&&x.UvEnds is not null),"native copied face pcurve boundary");var ends=face.Edges.Select(x=>x.UvEnds!.First).ToList();ends.Add(ends[0]);var polygon=MeshBoundaryComputations.Polygon2d(ends,.05,-3);Require(polygon.InputLower==-3&&polygon.NativeLower==1&&polygon.Points.Count==5&&polygon.Points[0]==polygon.Points[^1],"copied UV polygon bounds/closure");using var one=quality.CopyTriangulation();using var two=quality.CopyTriangulation();quality.Dispose();triangulation.Dispose();poly.Dispose();using var preserved=PolyDataWorkspaces.Copy(one);using var second=PolyDataWorkspaces.Copy(two);Require(preserved.Mesh.Triangles.SequenceEqual(exactMesh.Triangles)&&second.Mesh.Triangles.SequenceEqual(exactMesh.Triangles)&&preserved.Mesh.Positions.SequenceEqual(exactMesh.Positions)&&second.Mesh.Positions.SequenceEqual(exactMesh.Positions),"independent ordinal domain copies");
#if !DIRECT_MODULE_CONSUMER
  using var doc=XdeDocument.Create();string occurrence,assemblyEntry,referenceEntry;using(var transaction=doc.BeginTransaction("BE copied mesh source")){var part=doc.AddShape(meshed,"verified mesh");var assembly=doc.AddAssembly("mesh assembly");assemblyEntry=assembly.Entry;using var location=TopLocLocation.Identity;var component=doc.AddComponent(assembly,part,location);occurrence=component.Entry;using var associations=DocumentAssociationContext.Bind(doc.Projections);var target=doc.Projections.GetLabel(component.Entry);var reference=associations.NewChild(doc.Projections.GetLabel("0:1"));referenceEntry=reference.Entry;associations.ReplaceReferences([new(reference,target)]);Require(transaction.Commit(),"BC source association transaction");}string xbf=Path.Combine(root,"source.xbf");doc.Save(xbf);using var restored=XdeDocument.Open(xbf);using var persisted=DocumentAssociationContext.Bind(restored.Projections);Require(persisted.Snapshot(restored.Projections.GetLabel(referenceEntry)).ReferenceEntry==occurrence,"exact BC source reference after XDE reopen");var instance=restored.GetLabel(assemblyEntry).GetOccurrences().Single();
  using var window=new BatchAUVisibleWindow();using var viewer=OcctViewer.Create(window.Handle);window.Viewer=viewer;using var presentation=viewer.Display(instance);presentation.SetDisplayMode(ViewerDisplayMode.Shaded);viewer.SetProjection(ViewerProjection.Top);viewer.FitAll();viewer.Redraw();viewer.MoveTo(0,0);var before=window.Capture();window.Mouse(0x201,180,180,true);window.Mouse(0x202,180,180);window.Mouse(0x200,0,0);Require(viewer.GetSelection().Count==1&&ReferenceEquals(viewer.GetSelection().Single(),presentation),"actual HWND copied mesh selection");var after=window.Capture();int pixels=BatchAUVisibleWindow.Changed(before,after);Require(pixels>100,"actual visible mesh selection repaint: "+pixels);var items=viewer.GetSelectedItems();try{Require(items.Single().SourceIdentity?.OccurrenceEntry==occurrence,"exact saved mesh source identity");}finally{foreach(var item in items)item.Dispose();}using(var volume=viewer.SelectionQueries.CreatePointVolume(180,180)){presentation.Hide();Require(!volume.IsCurrent,"source visibility invalidates volume");}presentation.Show();viewer.FitAll();using(var volume=viewer.SelectionQueries.CreatePointVolume(180,180)){using var moved=GpTrsf.Create(1,0,0);presentation.SetTransform(moved);Require(!volume.IsCurrent,"source transform invalidates volume");}if(Environment.GetEnvironmentVariable("OCCTSHARP_BATCH_BE_EVIDENCE") is {} evidence){Directory.CreateDirectory(evidence);BatchAUVisibleWindow.SavePng(Path.Combine(evidence,"before.png"),before);BatchAUVisibleWindow.SavePng(Path.Combine(evidence,"selected.png"),after);File.WriteAllText(Path.Combine(evidence,"visible-result.json"),System.Text.Json.JsonSerializer.Serialize(new{state="PASS",pixels,occurrence,nodes=data.NodeCount,triangles=data.Triangles.Count,capture="DXGI composited client pixels",input="SendMessage HWND -> ViewerInputController",visibilityStale=true,transformStale=true}));}
#else
  // Preserve the accepted direct-module Viewer C ABI workflow as well as this batch's mesh chain.
  BatchAUIntegratedWorkflow.Run();
#endif
  Require(data.Triangles.Count>0&&polygon.Points.Count==5,"detached diagnostics after release");
 }finally{Directory.Delete(root,true);}}
}
